(function(E){ const x = E["exam-07"] = E["exam-07"] || {units:{}}; (x.units = x.units || {})["x07-s"] = {"id":"x07-s","patterns":["S1-frame","S1-leisure","S2-experience","S3-work","TR-short","PARA-discuss"],"title":{"en":"Speaking","tr":"Speaking","fa":"Speaking (صحبت کردن)"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions in two or three sentences, talk for two minutes about a piece of work you were proud of, and discuss job satisfaction with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: günlük soruları iki üç cümleyle cevaplayacak, gurur duyduğun bir iş hakkında iki dakika konuşacak ve iş tatminini bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره با دو سه جمله جواب بدهی، دو دقیقه درباره‌ی کاری که به آن افتخار کردی حرف بزنی و درباره‌ی رضایت شغلی با یک نظر، یک دلیل و یک مثال بحث کنی."},"sessions":[["explain"],["sets"],["exit"]],"explain":{"title":{"en":"Speaking: Parts 1, 2 and 3","tr":"Speaking: Part 1, 2 ve 3","fa":"Speaking: بخش‌های ۱، ۲ و ۳"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions in two or three sentences, talk for two minutes about a piece of work you were proud of, and discuss job satisfaction with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: günlük soruları iki üç cümleyle cevaplayacak, gurur duyduğun bir iş hakkında iki dakika konuşacak ve iş tatminini bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره با دو سه جمله جواب بدهی، دو دقیقه درباره‌ی کاری که به آن افتخار کردی حرف بزنی و درباره‌ی رضایت شغلی با یک نظر، یک دلیل و یک مثال بحث کنی."},"stats":[{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"11-14 min","tr":"11-14 dk","fa":"۱۱ تا ۱۴ دقیقه"}},{"label":{"en":"Parts","tr":"Kısım","fa":"بخش"},"value":"3"},{"label":{"en":"Part 2 talk","tr":"Part 2 konuşması","fa":"صحبت Part 2"},"value":{"en":"2 min","tr":"2 dk","fa":"۲ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: libraries, work you were proud of, job satisfaction","tr":"Bu sınav: kütüphaneler, gurur duyduğun iş, iş tatmini","fa":"این آزمون: کتابخانه، کاری که به آن افتخار کردی، رضایت شغلی"},"intro":{"en":"The three parts are linked: Part 1 is about you, Part 2 is one experience from a card, and Part 3 widens the Part 2 topic to people in general. Experiences are the most common Part 2 card.","tr":"Üç kısım birbirine bağlıdır: Part 1 seninle ilgili, Part 2 karttan tek bir deneyim ve Part 3, Part 2 konusunu genel olarak insanlara genişletir. Deneyimler en sık çıkan Part 2 kartıdır.","fa":"سه بخش به هم وصل‌اند: Part 1 درباره‌ی خودت است، Part 2 یک تجربه از روی کارت و Part 3 موضوع Part 2 را به آدم‌ها به‌طور کلی گسترش می‌دهد. تجربه‌ها رایج‌ترین کارت Part 2 هستند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x07-s1-ctx","exam":true,"patterns":["S1-frame","S1-leisure"],"often":{"pattern":"S1-leisure","n":10,"of":40,"label":{"en":"Comes up often in the real exam: 10 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 10’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۰ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 1: you, then libraries","tr":"Part 1: sen, sonra kütüphaneler","fa":"Part 1: خودت، بعد کتابخانه‌ها"},"asks":{"en":"The examiner checks your name and asks about your work, studies or home, then four questions on one everyday topic. Here the topic is libraries.","tr":"Sınav görevlisi adını kontrol eder, işini, okulunu ya da evini sorar, sonra günlük bir konuda dört soru sorar. Burada konu kütüphaneler.","fa":"ممتحن اسمت را چک می‌کند، درباره‌ی کار، درس یا خانه‌ات می‌پرسد و بعد چهار سؤال درباره‌ی یک موضوع روزمره. این‌جا موضوع کتابخانه است."},"fields":["Work or studies","Home","Using libraries now","Libraries as a child","What libraries offer","The future of libraries"],"words":[{"a":"borrow","b":"take out a book for a few weeks","tr":"ödünç almak","fa":"امانت گرفتن"},{"a":"a quiet place to study","b":"somewhere calm to work","tr":"çalışmak için sessiz bir yer","fa":"جای آرام برای درس خواندن"},{"a":"membership","b":"a library card","tr":"üyelik","fa":"عضویت"},{"a":"e-books","b":"books you read on a screen","tr":"e-kitaplar","fa":"کتاب الکترونیکی"},{"a":"I used to","b":"when I was younger, I would","tr":"eskiden ... -ardım","fa":"قبلاً ... می‌کردم"},{"a":"these days","b":"nowadays / at the moment","tr":"bugünlerde","fa":"این روزها"},{"a":"free of charge","b":"it doesn’t cost anything","tr":"ücretsiz","fa":"رایگان"},{"a":"events","b":"talks, clubs and workshops","tr":"etkinlikler","fa":"برنامه‌ها، رویدادها"},{"a":"I doubt it","b":"I don’t think so","tr":"sanmıyorum","fa":"فکر نمی‌کنم"},{"a":"still useful","b":"still have a purpose","tr":"hâlâ yararlı","fa":"هنوز مفید"}],"traps":[{"en":"One-word answers: \"Rarely.\" Give the answer and a reason or detail.","tr":"Tek kelimelik cevaplar: \"Nadiren.\" Cevabı ve bir neden ya da ayrıntı ver.","fa":"جواب‌های یک‌کلمه‌ای: «به‌ندرت.». جواب و یک دلیل یا جزئیات بده."},{"en":"Talking about libraries in general for a minute. In Part 1, talk about you, briefly.","tr":"Bir dakika boyunca genel olarak kütüphanelerden söz etmek. Part 1’de kısaca kendinden söz et.","fa":"یک دقیقه درباره‌ی کتابخانه به‌طور کلی حرف زدن. در Part 1 کوتاه درباره‌ی خودت حرف بزن."}],"example":{"text":"Q: \"How often do you go to a library?\"","item":"Which answer is the right length?","answer":"Only now and then, to be honest. I read mostly on my phone, but I go to the city library when I need a quiet place to study.","why":{"en":"An answer, a reason and a detail: about ten seconds.","tr":"Bir cevap, bir neden ve bir ayrıntı: yaklaşık on saniye.","fa":"یک جواب، یک دلیل و یک جزئیات: حدود ده ثانیه."}}},{"id":"x07-s2-ctx","exam":true,"patterns":["S2-experience","PARA-discuss"],"often":{"pattern":"S2-experience","n":17,"of":40,"label":{"en":"Comes up often in the real exam: 17 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 2: a piece of work you were proud of","tr":"Part 2: gurur duyduğun bir iş","fa":"Part 2: کاری که به آن افتخار کردی"},"asks":{"en":"The card asks you to describe a piece of work or study that gave you great satisfaction: what it was, when you did it, how you did it, and why it made you proud.","tr":"Kart, sana büyük bir tatmin veren bir iş ya da çalışmayı anlatmanı istiyor: ne olduğu, ne zaman yaptığın, nasıl yaptığın ve seni neden gururlandırdığı.","fa":"کارت از تو می‌خواهد کار یا درسی را توصیف کنی که خیلی راضی‌ات کرد: چه بود، کی انجامش دادی، چطور انجامش دادی و چرا به آن افتخار کردی."},"fields":["What it was","When you did it","How you did it","Why it was satisfying"],"words":[{"a":"a project","b":"a piece of work with a goal","tr":"proje","fa":"پروژه"},{"a":"it took me","b":"I spent ... on it","tr":"... sürdü","fa":"... طول کشید"},{"a":"challenging","b":"difficult but interesting","tr":"zorlu","fa":"چالش‌برانگیز"},{"a":"I had to","b":"it was necessary to","tr":"... zorundaydım","fa":"مجبور بودم"},{"a":"in the end","b":"finally / eventually","tr":"sonunda","fa":"آخرش"},{"a":"it paid off","b":"the effort was worth it","tr":"emeğe değdi","fa":"زحمتش به ثمر نشست"},{"a":"proud of","b":"pleased with what I achieved","tr":"... ile gurur duymak","fa":"افتخار کردن به"},{"a":"a sense of achievement","b":"the feeling of having done something well","tr":"başarı duygusu","fa":"حس موفقیت"},{"a":"feedback","b":"comments from others","tr":"geri bildirim","fa":"بازخورد"},{"a":"it taught me","b":"I learned from it","tr":"bana ... öğretti","fa":"به من یاد داد"}],"traps":[{"en":"Describing the work and never saying why it was satisfying. The explain line is where you reach two minutes.","tr":"İşi anlatıp neden tatmin edici olduğunu hiç söylememek. Açıklama satırı iki dakikaya ulaştığın yerdir.","fa":"توصیف کار بدون اینکه بگویی چرا راضی‌ات کرد. خط توضیح جایی است که به دو دقیقه می‌رسی."},{"en":"Choosing something too small to talk about for long. Pick a task with a challenge and a result.","tr":"Uzun süre konuşulamayacak kadar küçük bir şey seçmek. Zorluğu ve sonucu olan bir iş seç.","fa":"انتخاب چیزی آن‌قدر کوچک که نمی‌شود زیاد درباره‌اش حرف زد. کاری را انتخاب کن که چالش و نتیجه داشته باشد."}],"example":{"text":"Notes: website for aunt’s bakery · last summer · learned code from videos · orders doubled → proud: did it alone","item":"How do you start?","answer":"I’d like to talk about a website I built last summer for my aunt’s small bakery, because it’s the piece of work I’m proudest of.","why":{"en":"It names the work and the time, and points to the explain line.","tr":"İşi ve zamanı söylüyor ve açıklama satırına işaret ediyor.","fa":"کار و زمان را می‌گوید و به خط توضیح اشاره می‌کند."}}},{"id":"x07-s3-ctx","exam":true,"patterns":["S3-work","PARA-discuss"],"often":{"pattern":"S3-work","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 3: job satisfaction and ambition","tr":"Part 3: iş tatmini ve hırs","fa":"Part 3: رضایت شغلی و جاه‌طلبی"},"asks":{"en":"The examiner widens the Part 2 topic: what makes people satisfied at work, whether pay matters more than colleagues, and whether ambition is always a good thing.","tr":"Sınav görevlisi Part 2 konusunu genişletir: insanları işte neyin tatmin ettiği, paranın mı iş arkadaşlarının mı daha önemli olduğu ve hırsın her zaman iyi bir şey olup olmadığı.","fa":"ممتحن موضوع Part 2 را گسترده‌تر می‌کند: چه چیزی آدم‌ها را در کار راضی می‌کند، آیا حقوق مهم‌تر است یا همکارها و آیا جاه‌طلبی همیشه چیز خوبی است."},"fields":["What makes work satisfying","Pay or colleagues","Changing jobs","Ambition","Success","Work and life balance"],"words":[{"a":"job satisfaction","b":"enjoying and valuing your work","tr":"iş tatmini","fa":"رضایت شغلی"},{"a":"a sense of purpose","b":"feeling your work matters","tr":"amaç duygusu","fa":"حس هدفمندی"},{"a":"recognition","b":"being noticed and thanked","tr":"takdir","fa":"قدردانی"},{"a":"a good salary","b":"well-paid work","tr":"iyi bir maaş","fa":"حقوق خوب"},{"a":"colleagues","b":"the people you work with","tr":"iş arkadaşları","fa":"همکارها"},{"a":"ambitious","b":"wanting to succeed and get ahead","tr":"hırslı","fa":"جاه‌طلب"},{"a":"burn out","b":"become exhausted from too much work","tr":"tükenmek","fa":"فرسوده شدن"},{"a":"promotion","b":"a move to a higher position","tr":"terfi","fa":"ارتقای شغلی"},{"a":"it depends on","b":"it varies with","tr":"... bağlı","fa":"بستگی دارد به"},{"a":"on the other hand","b":"that said / then again","tr":"öte yandan","fa":"از طرف دیگر"}],"traps":[{"en":"Answering only about your own job. Part 3 asks about people in general.","tr":"Yalnızca kendi işin hakkında konuşmak. Part 3 genel olarak insanları sorar.","fa":"فقط درباره‌ی کار خودت حرف زدن. Part 3 درباره‌ی آدم‌ها به‌طور کلی است."},{"en":"A view with no reason: \"Pay is more important.\" Say why, and give an example.","tr":"Nedensiz bir görüş: \"Maaş daha önemli.\" Nedenini söyle ve bir örnek ver.","fa":"نظر بدون دلیل: «حقوق مهم‌تر است». بگو چرا و یک مثال بیاور."}],"example":{"text":"Q: \"Is it better to have a well-paid job or a job you enjoy?\"","item":"Which answer has a view, a reason and an example?","answer":"I’d choose enjoyment, as long as the pay is enough to live on. You spend so much of your life at work that hating it affects everything. A friend of mine took a pay cut to teach music, and she says it was the best decision she ever made.","why":{"en":"View, a reason and a real example, with a small limit (\"as long as\").","tr":"Görüş, bir neden ve gerçek bir örnek, küçük bir sınırla (\"as long as\").","fa":"نظر، یک دلیل و یک مثال واقعی، با یک محدودیت کوچک («as long as»)."}}},{"id":"S2-exp-task","ctx":["S2-experience","S2-exp-task"],"title":{"en":"Something you did: a task, a skill, help","tr":"Yaptığın bir şey: bir iş, bir beceri, bir yardım","fa":"کاری که کردی: یک کار، یک مهارت، یک کمک"},"asks":{"en":"A card about something you achieved or did: satisfying work, learning to cook something, a difficult task, doing something in a hurry, fixing something, helping someone. The prompts ask what, when, how it went, and how you felt.","tr":"Başardığın ya da yaptığın bir şey hakkında kart: tatmin edici bir iş, bir yemeği yapmayı öğrenmek, zor bir görev, aceleyle yapılan bir iş, bir şeyi tamir etmek, birine yardım etmek. Maddeler ne olduğunu, ne zaman olduğunu, nasıl geçtiğini ve ne hissettiğini sorar.","fa":"کارتی درباره‌ی کاری که انجام دادی یا موفق به آن شدی: کاری رضایت‌بخش، یاد گرفتن پختن یک غذا، یک کار سخت، کاری که با عجله کردی، تعمیر چیزی، کمک به کسی. بندها می‌پرسند چه بود، کی، چطور پیش رفت و چه حسی داشتی."},"fields":["Describe a time you learned to cook a new dish.","Describe a difficult task you completed.","Describe a time you had to do something in a hurry.","Describe a time you fixed something.","Describe a piece of work that made you proud."],"words":[{"a":"it was hard","b":"it was a real challenge","tr":"gerçek bir meydan okumaydı","fa":"واقعاً چالش بود"},{"a":"I tried","b":"I had a go at","tr":"... denedim","fa":"امتحانش کردم"},{"a":"I did it","b":"I managed to / I pulled it off","tr":"başardım","fa":"از پسش برآمدم"},{"a":"I made mistakes","b":"it went wrong the first time","tr":"ilk seferde ters gitti","fa":"دفعه‌ی اول خراب شد"},{"a":"I didn't stop","b":"I kept going / I didn't give up","tr":"pes etmedim","fa":"ول نکردم"},{"a":"in a hurry","b":"at the last minute / against the clock","tr":"son dakikada","fa":"دقیقه‌ی نود"},{"a":"proud","b":"it gave me a real sense of achievement","tr":"büyük bir başarı duygusu verdi","fa":"حس موفقیت واقعی به من داد"},{"a":"nervous","b":"my heart was racing","tr":"kalbim küt küt atıyordu","fa":"قلبم تند می‌زد"},{"a":"relieved","b":"what a relief","tr":"ne büyük rahatlama","fa":"چه خیالم راحت شد"},{"a":"someone showed me","b":"my neighbour talked me through it","tr":"komşum adım adım anlattı","fa":"همسایه‌ام قدم به قدم راهنمایی‌ام کرد"},{"a":"I learned","b":"it taught me that","tr":"bana ... öğretti","fa":"به من یاد داد که"},{"a":"looking back","b":"when I think about it now","tr":"şimdi düşününce","fa":"حالا که فکرش را می‌کنم"}],"traps":[{"en":"Past continuous for the background (\"I was living alone...\"), past simple for the events (\"then I called...\").","tr":"Arka plan için geçmiş zamanda süreklilik (\"I was living alone...\"), olaylar için geçmiş zaman (\"then I called...\").","fa":"برای پس‌زمینه گذشته‌ی استمراری («I was living alone...»)، برای رویدادها گذشته‌ی ساده («then I called...»)."},{"en":"A story with no problem is short. Put one difficulty in the middle; that is where the talk grows.","tr":"Sorunsuz bir hikâye kısa olur. Ortaya bir zorluk koy; konuşma orada büyür.","fa":"داستان بدون مشکل کوتاه است. یک سختی وسطش بگذار؛ صحبت همان‌جا گسترش پیدا می‌کند."}],"example":{"lines":[["Candidate","Last winter I was living alone for the first time, and one night the kitchen tap started leaking."],["Candidate","I didn’t want to wait two days for a plumber, so I watched a video and had a go at fixing it myself."],["Candidate","The first washer I bought was the wrong size, which was really annoying."]],"item":"Which tenses carry the background and which carry the events?","answer":"Past continuous for the background (I was living alone); past simple for the events (started, watched, bought).","why":{"en":"The two tenses tell the listener what was happening and what happened.","tr":"İki zaman dinleyene neyin sürmekte olduğunu ve neyin olduğunu söyler.","fa":"این دو زمان به شنونده می‌گویند چه چیزی در جریان بود و چه اتفاقی افتاد."}},"ideas":["the situation before you started","one thing that went wrong","how you solved it","how you felt at the end","what you learned (explain)"],"general":true,"patterns":["S2-experience"],"often":{"pattern":"S2-experience","n":17,"of":40,"label":{"en":"Comes up often in the real exam: 17 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ آزمون از ۴۰ آزمونِ اخیر"}}},{"id":"S3-work","ctx":["S3-work"],"title":{"en":"Work, careers and satisfaction","tr":"İş, kariyer ve iş tatmini","fa":"کار، مسیر شغلی و رضایت"},"asks":{"en":"General questions linked to the Part 2 card, about job satisfaction, long hours, communication at work and good workplaces. The examiner wants an opinion, a reason, an example and, when it helps, the other side.","tr":"Part 2 kartına bağlı, iş tatmini, uzun çalışma saatleri, iş yerinde iletişim ve iyi iş yerleri hakkında genel sorular. Sınav görevlisi bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"سؤال‌های کلی مرتبط با کارت Part 2، درباره‌ی رضایت شغلی، ساعت‌های کاری طولانی، ارتباط در محل کار و محیط کار خوب. ممتحن یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},"fields":["What makes a job satisfying?","Do people work longer hours than in the past?","Is it better to work in a team or alone?","What makes a good manager?","Will robots take people’s jobs?"],"words":[{"a":"a good job","b":"a rewarding / fulfilling job","tr":"tatmin edici bir iş","fa":"شغلی رضایت‌بخش"},{"a":"money","b":"salary / pay","tr":"maaş","fa":"حقوق"},{"a":"too much work","b":"a heavy workload / burnout","tr":"aşırı iş yükü, tükenmişlik","fa":"فشار کاری زیاد، فرسودگی"},{"a":"free time","b":"work-life balance","tr":"iş-yaşam dengesi","fa":"تعادل کار و زندگی"},{"a":"the boss","b":"a manager / a supervisor","tr":"yönetici","fa":"مدیر"},{"a":"colleagues","b":"co-workers / the team","tr":"iş arkadaşları","fa":"همکاران"},{"a":"talk clearly","b":"communicate effectively","tr":"etkili iletişim kurmak","fa":"ارتباط مؤثر برقرار کردن"},{"a":"work from home","b":"work remotely","tr":"uzaktan çalışmak","fa":"دورکاری کردن"},{"a":"moving up","b":"career progression / promotion","tr":"kariyerde ilerleme","fa":"پیشرفت شغلی"},{"a":"machines","b":"automation / artificial intelligence","tr":"otomasyon, yapay zekâ","fa":"خودکارسازی، هوش مصنوعی"},{"a":"safe job","b":"job security","tr":"iş güvencesi","fa":"امنیت شغلی"},{"a":"feel valued","b":"be appreciated","tr":"değer görmek","fa":"قدر دیده شدن"}],"traps":[{"en":"Prediction questions (\"Will...?\") need will, might or is likely to, plus a reason.","tr":"Tahmin soruları (\"Will...?\") will, might ya da is likely to ve bir neden ister.","fa":"سؤال‌های پیش‌بینی («Will...?») will، might یا is likely to و یک دلیل می‌خواهند."},{"en":"Avoid \"it depends\" with nothing after it. Say what it depends on.","tr":"Arkası gelmeyen \"duruma bağlı\" deme. Neye bağlı olduğunu söyle.","fa":"«بستگی دارد» را بدون ادامه نگو. بگو به چه بستگی دارد."}],"example":{"lines":[["Examiner","Will robots take people’s jobs in the future?"],["Candidate","Some jobs, probably, especially repetitive ones like checking goods in a warehouse."],["Candidate","But I think most jobs will change rather than disappear, because people will still be needed to make decisions and deal with customers."]],"item":"How does the speaker answer a prediction question?","answer":"A cautious prediction (\"probably\"), an example, then a second prediction with \"will\" and a reason.","why":{"en":"Hedging words (probably, I think) suit questions about the future.","tr":"Temkinli kelimeler (probably, I think) gelecekle ilgili sorulara uygundur.","fa":"کلمه‌های محتاطانه (probably، I think) برای سؤال‌های آینده مناسب‌اند."}},"ideas":["satisfaction comes from feeling useful, not only pay","technology made work faster but longer","teams share ideas; alone you focus better","robots replace tasks, not whole jobs"],"general":true,"patterns":["S3-work"],"often":{"pattern":"S3-work","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three parts, one examiner","tr":"Üç kısım, bir sınav görevlisi","fa":"سه بخش، یک ممتحن"},"body":{"en":"Part 1 (4-5 minutes): questions about you and one everyday topic. Part 2 (3-4 minutes): one minute to prepare, then up to two minutes alone, then one short question. Part 3 (4-5 minutes): a discussion of general questions. The test is recorded.","tr":"Part 1 (4-5 dakika): seninle ve günlük bir konuyla ilgili sorular. Part 2 (3-4 dakika): bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma, sonra kısa bir soru. Part 3 (4-5 dakika): genel soruların tartışması. Sınav kaydedilir.","fa":"Part 1 (۴ تا ۵ دقیقه): سؤال‌هایی درباره‌ی خودت و یک موضوع روزمره. Part 2 (۳ تا ۴ دقیقه): یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی و بعد یک سؤال کوتاه. Part 3 (۴ تا ۵ دقیقه): بحث درباره‌ی سؤال‌های کلی. آزمون ضبط می‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One move for each part","tr":"Her kısım için bir hamle","fa":"برای هر بخش یک حرکت"},"steps":[{"en":"Part 1: answer, then add a reason or a detail. Two or three sentences.","tr":"Part 1: cevapla, sonra bir neden ya da ayrıntı ekle. İki üç cümle.","fa":"Part 1: جواب بده، بعد یک دلیل یا جزئیات اضافه کن. دو سه جمله."},{"en":"Part 2: in the minute, note the work, one difficulty, the result and why you were proud.","tr":"Part 2: o bir dakikada işi, bir zorluğu, sonucu ve neden gurur duyduğunu not et.","fa":"Part 2: در آن یک دقیقه کار، یک سختی، نتیجه و دلیل افتخارت را یادداشت کن."},{"en":"Part 2: tell the story in order and spend the most time on why it was satisfying.","tr":"Part 2: hikâyeyi sırayla anlat ve en çok zamanı neden tatmin edici olduğuna ayır.","fa":"Part 2: داستان را به ترتیب بگو و بیشترین وقت را روی اینکه چرا راضی‌ات کرد بگذار."},{"en":"Part 3: give a view, a reason, an example, and the other side when it helps.","tr":"Part 3: bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ver.","fa":"Part 3: یک نظر، یک دلیل، یک مثال و هرجا کمک کرد طرف مقابل را بگو."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Describing effort and result","tr":"Emeği ve sonucu anlatmak","fa":"توصیف تلاش و نتیجه"},"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["the task (past simple)","I designed the whole thing myself."],["the difficulty","The hardest part was..."],["effort over time (past continuous)","I was working on it every evening for a month."],["the result","In the end, it paid off: ..."],["why it was satisfying","What made me proudest was that..."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A Part 3 answer, step by step","tr":"Bir Part 3 cevabı, adım adım","fa":"یک جواب Part 3، قدم به قدم"},"instruction":"Examiner: \"Do you think people today change jobs too often?\"","item":"Answer with four moves.","answer":"In some cases, yes. Young people in particular move every year or two, so they never build deep skills in one place. A cousin of mine has had five jobs in six years. That said, changing jobs can be the quickest way to get a better salary.","walk":[{"en":"View: \"In some cases, yes.\"","tr":"Görüş: \"In some cases, yes.\"","fa":"نظر: «In some cases, yes.»"},{"en":"Reason and example: no deep skills; the cousin with five jobs.","tr":"Neden ve örnek: derin beceri yok; beş iş değiştiren kuzen.","fa":"دلیل و مثال: مهارت عمیق ساخته نمی‌شود؛ پسرخاله‌ای که پنج شغل عوض کرده."},{"en":"The other side: \"That said, changing jobs can be...\"","tr":"Karşı taraf: \"That said, changing jobs can be...\"","fa":"طرف مقابل: «That said, changing jobs can be...»"}]},"quick":{"prompt":"Part 1. Examiner: \"Did you use libraries when you were a child?\" Which answer is best?","options":["Yes.","Libraries were first opened to the public in the nineteenth century, and today...","Yes, every Saturday. My mother took me, and I always came home with far too many books."],"correct":2,"why":{"en":"An answer plus a detail and a small story. \"Yes.\" is too short; the history of libraries is a lecture, not a conversation.","tr":"Bir cevap, bir ayrıntı ve küçük bir anı. \"Yes.\" çok kısa; kütüphanelerin tarihi sohbet değil, ders.","fa":"یک جواب با یک جزئیات و یک خاطره‌ی کوچک. «Yes.» خیلی کوتاه است؛ تاریخچه‌ی کتابخانه‌ها سخنرانی است، نه گفتگو."}},"remember":{"en":"Part 1 short and natural, Part 2 the work, the effort and why you were proud, Part 3 view, reason, example.","tr":"Part 1 kısa ve doğal, Part 2 iş, emek ve neden gurur duyduğun, Part 3 görüş, neden, örnek.","fa":"Part 1 کوتاه و طبیعی، Part 2 کار، زحمت و دلیل افتخار، Part 3 نظر، دلیل، مثال."},"type":"explain","id":"c-x07-s-e","course":"ielts-exams","exam":"exam-07","unit":"x07-s"},"sets":{"title":{"en":"The Speaking test","tr":"Speaking sınavı","fa":"آزمون Speaking"},"note":{"en":"Do the three parts in order, without a break, as in the real test. Record yourself if you can, then use the self-check under each part.","tr":"Gerçek sınavdaki gibi üç kısmı sırayla ve ara vermeden yap. Yapabilirsen kendini kaydet, sonra her kısmın altındaki öz değerlendirmeyi kullan.","fa":"سه بخش را به ترتیب و بدون مکث انجام بده، مثل آزمون واقعی. اگر می‌توانی صدایت را ضبط کن و بعد از خودارزیابیِ زیر هر بخش استفاده کن."},"sequential":true,"examinerVoice":{"accent":"British (standard Southern)","gender":"F","tts":{"engine":"kokoro","voice":"bf_alice"},"role":"Examiner"},"sets":[{"part":"Part 1","ctx":["S1-frame","S1-leisure"],"minutes":[4,5],"title":{"en":"Part 1: about you, then libraries","tr":"Part 1: senin hakkında, sonra kütüphaneler","fa":"Part 1: درباره‌ی خودت، بعد کتابخانه‌ها"},"examinerIntro":["Good evening. My name is Joanna Pike. Can you tell me your full name, please?","Thank you. And can I see your identification, please?","Thank you. Now, in this first part, I’d like to ask you some questions about yourself."],"frame":["Do you work or are you a student?","What is the most difficult part of your work or your studies?"],"topicIntro":"Now let’s talk about libraries.","questions":["How often do you go to a library?","Did you use libraries when you were a child? [Why/Why not?]","What do you think libraries should offer apart from books?","Do you think people will still use libraries in the future?"],"model":"Q: How often do you go to a library?\nA: About once a fortnight. There’s a small library near my office, and I go there at lunchtime when I need somewhere quiet to read.\n\nQ: Did you use libraries when you were a child?\nA: All the time. My grandfather took me every Saturday, and I was allowed to borrow six books, which felt like a fortune.\n\nQ: What do you think libraries should offer apart from books?\nA: Free computers, definitely, because not everyone has one at home. Mine also runs language clubs, which are really popular.\n\nQ: Do you think people will still use libraries in the future?\nA: I think so, but in a different way. Fewer people may borrow paper books, but they’ll still need quiet spaces and free internet.","moves":[{"label":{"en":"Answer first","tr":"Önce cevap","fa":"اول جواب"},"example":"About once a fortnight."},{"label":{"en":"Add a reason or a detail","tr":"Bir neden ya da ayrıntı ekle","fa":"یک دلیل یا جزئیات اضافه کن"},"example":"There’s a small library near my office, and I go there at lunchtime..."},{"label":{"en":"A small contrast or a then/now","tr":"Küçük bir karşıtlık ya da o zaman/şimdi","fa":"یک تضاد کوچک یا «آن موقع/حالا»"},"example":"Fewer people may borrow paper books, but they’ll still need quiet spaces..."}],"selfCheck":[{"en":"I answered every question with two or three sentences, not one word.","tr":"Her soruyu tek kelimeyle değil, iki üç cümleyle cevapladım.","fa":"به هر سؤال با دو سه جمله جواب دادم، نه یک کلمه."},{"en":"I added a reason or a detail after each answer.","tr":"Her cevaptan sonra bir neden ya da ayrıntı ekledim.","fa":"بعد از هر جواب یک دلیل یا جزئیات اضافه کردم."},{"en":"I used the past for childhood and will or may for the future.","tr":"Çocukluk için geçmiş zamanı, gelecek için will ya da may kullandım.","fa":"برای بچگی از گذشته و برای آینده از will یا may استفاده کردم."}]},{"part":"Part 2","ctx":["S2-experience"],"minutes":[3,4],"title":{"en":"Part 2: a piece of work you were proud of","tr":"Part 2: gurur duyduğun bir iş","fa":"Part 2: کاری که به آن افتخار کردی"},"examinerIntro":["Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. Before you talk, you’ll have one minute to think about what you’re going to say. You can make some notes if you wish. Do you understand?","Here’s some paper and a pencil for making notes, and here’s your topic. I’d like you to describe a piece of work or study that you were very proud of.","All right? Remember you have one to two minutes for this. Don’t worry if I stop you. I’ll tell you when the time is up. Can you start speaking now, please?"],"card":{"task":"Describe a piece of work or study that you were very proud of.","bullets":["what the work was","when you did it","how you did it","and explain why it gave you so much satisfaction"]},"prep":60,"talk":120,"roundingOff":["Do you prefer to work alone or in a team?"],"model":"I’d like to talk about a website I built last summer for my aunt’s small bakery, because it’s the piece of work I’m proudest of.\n\nMy aunt has run the bakery for twenty years, but she had no online presence at all, and younger customers were going to a chain store down the road instead. She couldn’t afford to pay a designer, so I offered to do it, even though I’d never built a website before.\n\nI was working on it every evening for about six weeks. I learned the basics from free online videos, took photos of her bread and cakes in the shop, and wrote short descriptions of each one. The hardest part was the ordering system, because it had to be simple enough for my aunt to use. It broke twice before I got it right.\n\nSo why did it give me so much satisfaction? Partly because of the result: within three months, her weekend orders had almost doubled, and she now has to bake extra on Saturdays. But mostly because I did it entirely myself. Nobody showed me how, and there were several moments when I almost gave up. Every time I walk past the shop and see people collecting their online orders, I feel a real sense of achievement.","moves":[{"label":{"en":"Start with what and when","tr":"Ne ve ne zamanla başla","fa":"با «چه» و «کی» شروع کن"},"example":"I’d like to talk about a website I built last summer for my aunt’s small bakery..."},{"label":{"en":"Describe how you did it, with a difficulty","tr":"Nasıl yaptığını bir zorlukla anlat","fa":"بگو چطور انجامش دادی، با یک سختی"},"example":"The hardest part was the ordering system... It broke twice before I got it right."},{"label":{"en":"Spend time on why it was satisfying","tr":"Neden tatmin edici olduğuna zaman ayır","fa":"روی دلیل رضایت وقت بگذار"},"example":"Partly because of the result... But mostly because I did it entirely myself."}],"selfCheck":[{"en":"I covered all four lines of the card and spoke for close to two minutes.","tr":"Kartın dört satırının hepsini ele aldım ve iki dakikaya yakın konuştum.","fa":"هر چهار خط کارت را گفتم و نزدیک دو دقیقه حرف زدم."},{"en":"I described at least one difficulty and how I solved it.","tr":"En az bir zorluğu ve onu nasıl çözdüğümü anlattım.","fa":"دست‌کم یک سختی و راه حلش را توصیف کردم."},{"en":"I gave more than one reason for feeling proud.","tr":"Gurur duymam için birden fazla neden verdim.","fa":"برای افتخار کردنم بیش از یک دلیل آوردم."}]},{"part":"Part 3","ctx":["S3-work"],"minutes":[4,5],"title":{"en":"Part 3: job satisfaction and ambition","tr":"Part 3: iş tatmini ve hırs","fa":"Part 3: رضایت شغلی و جاه‌طلبی"},"examinerIntro":["We’ve been talking about a piece of work you were proud of, and I’d like to discuss with you one or two more general questions related to this."],"subtopics":[{"title":"Job satisfaction","questions":["What makes people feel satisfied with their work?","Is a good salary more important than having friendly colleagues?","Why do some people stay in jobs they do not enjoy?"]},{"title":"Ambition","questions":["Is it always a good thing to be ambitious?","Do you think young people today are more ambitious than their parents were?","How can a person have a successful career and still have a good life outside work?"]}],"model":"Q: Is a good salary more important than having friendly colleagues?\nA: For most people, I’d say colleagues matter more once the salary is reasonable. You spend eight hours a day with them, and a bad atmosphere can make even a well-paid job miserable. My brother left a bank job with an excellent salary because his team never spoke to each other. That said, if someone is struggling to pay the rent, the salary obviously comes first.\n\nQ: Is it always a good thing to be ambitious?\nA: Not always. Ambition pushes people to learn and improve, which is good for them and for society. But when it becomes the only thing that matters, people can burn out or treat others badly to get ahead. I think the healthiest kind of ambition is about doing good work, not just about getting promoted.","moves":[{"label":{"en":"Give a clear view","tr":"Net bir görüş ver","fa":"نظرت را روشن بگو"},"example":"For most people, I’d say colleagues matter more once the salary is reasonable."},{"label":{"en":"Support it: reason + example","tr":"Destekle: neden + örnek","fa":"پشتیبانی کن: دلیل + مثال"},"example":"My brother left a bank job with an excellent salary because his team never spoke to each other."},{"label":{"en":"Show the other side or a limit","tr":"Karşı tarafı ya da bir sınırı göster","fa":"طرف مقابل یا یک محدودیت را نشان بده"},"example":"That said, if someone is struggling to pay the rent, the salary obviously comes first."}],"selfCheck":[{"en":"I gave a clear view in my first sentence.","tr":"İlk cümlemde net bir görüş verdim.","fa":"در جمله‌ی اولم نظر روشنی دادم."},{"en":"I supported it with a reason and a real example.","tr":"Onu bir neden ve gerçek bir örnekle destekledim.","fa":"آن را با یک دلیل و یک مثال واقعی پشتیبانی کردم."},{"en":"I talked about people in general, not only about myself.","tr":"Yalnızca kendimden değil, genel olarak insanlardan söz ettim.","fa":"درباره‌ی آدم‌ها به‌طور کلی حرف زدم، نه فقط خودم."}]}],"type":"sets","id":"c-x07-s-p","course":"ielts-exams","exam":"exam-07","unit":"x07-s"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"I was given a promotion last year.\" A promotion is...","options":["a pay cut","a move to a higher position at work","a holiday"],"correct":1,"why":{"en":"Promotion = moving up to a more senior job.","tr":"Promotion = daha üst bir göreve geçmek.","fa":"promotion یعنی رفتن به یک جایگاه بالاتر در کار."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means \"become exhausted because of too much work\"?","options":["burn out","get ahead","take over"],"correct":0,"why":{"en":"To burn out = to be so tired from work that you cannot continue.","tr":"Burn out = işten devam edemeyecek kadar yorulmak.","fa":"burn out یعنی آن‌قدر از کار خسته شدن که نتوانی ادامه بدهی."}},{"tests":"method","point":2,"prompt":"Your card ends \"and explain why it gave you so much satisfaction\". How should you use your minute?","options":["Write the whole first paragraph","Only note when you did it","Note two or three reasons for the last line"],"correct":2,"why":{"en":"Several reasons on the last line help you speak for the full two minutes.","tr":"Son satır için birkaç neden, iki dakikanın tamamını konuşmana yardım eder.","fa":"چند دلیل برای خط آخر کمک می‌کند کل دو دقیقه را حرف بزنی."}},{"tests":"trap","point":2,"prompt":"After describing the work for a minute, you stop. The examiner waits. What should you have done?","options":["Repeated what the work was","Explained why it was satisfying, with reasons and a result","Asked the examiner a question"],"correct":1,"why":{"en":"The explain line is the part that carries the talk to two minutes.","tr":"Açıklama satırı konuşmayı iki dakikaya taşıyan kısımdır.","fa":"خط توضیح بخشی است که صحبت را تا دو دقیقه می‌رساند."}},{"tests":"method","point":2,"prompt":"Part 3: \"Should companies pay for staff to study?\" Which answer has the most complete structure?","options":["Yes, in many cases. Better-trained staff do better work; my company paid for my evening course. It may not suit very small firms, though.","Yes, definitely.","My company paid for my course."],"correct":0,"why":{"en":"The first answer has a view, a reason, an example and a limit.","tr":"İlk cevapta görüş, neden, örnek ve bir sınır var.","fa":"جواب اول نظر، دلیل، مثال و یک محدودیت دارد."}}],"id":"c-x07-s-x","course":"ielts-exams","exam":"exam-07","unit":"x07-s"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
